// Enhanced feedback generation for pipeline tasks
const fs = require('fs');
const { exec } = require('child_process');

// Extract task information from incoming message
const taskName = msg.task_name || 'unknown';
const exitCode = msg.payload.code || 0;
const stdout = msg.payload.stdout || '';
const stderr = msg.payload.stderr || '';
const timestamp = new Date().toLocaleString();

// Generate comprehensive feedback
let feedback = {
    timestamp: timestamp,
    task_name: taskName,
    status: exitCode === 0 ? 'success' : 'failed',
    exit_code: exitCode,
    duration: msg.duration || 'unknown',
    output_size: stdout.length + stderr.length,
    statistics: null,
    user_message: '',
    detailed_info: ''
};

// Generate user-friendly messages
if (exitCode === 0) {
    feedback.user_message = `✅ ${taskName.toUpperCase()} COMPLETED SUCCESSFULLY`;
    feedback.detailed_info = `Task finished at ${timestamp}\n`;

    // Parse output for statistics
    if (stdout.includes('Power Rating')) {
        const ratings = stdout.match(/Power Rating: ([\d\.]+)/g);
        if (ratings) {
            feedback.detailed_info += `🔢 Generated ${ratings.length} power ratings\n`;
        }
    }

    if (stdout.includes('Monte Carlo')) {
        const simulations = stdout.match(/simulation/gi);
        if (simulations) {
            feedback.detailed_info += `🎲 Completed ${simulations.length} Monte Carlo simulations\n`;
        }
    }

    if (stdout.includes('Model')) {
        const models = stdout.match(/model trained/gi);
        if (models) {
            feedback.detailed_info += `🤖 Trained ${models.length} ML models\n`;
        }
    }

    // Data processing stats
    if (stdout.includes('processed')) {
        const processed = stdout.match /(\d+)\s+records?\s+processed/gi);
        if (processed) {
            feedback.detailed_info += `📊 ${processed[0]}\n`;
        }
    }

    feedback.detailed_info += `📈 Output size: ${(feedback.output_size / 1024).toFixed(2)} KB`;

} else {
    feedback.user_message = `❌ ${taskName.toUpperCase()} FAILED`;
    feedback.detailed_info = `Task failed at ${timestamp}\n`;
    feedback.detailed_info += `❌ Exit code: ${exitCode}\n`;

    if (stderr) {
        const errorLines = stderr.split('\n').slice(0, 3); // First 3 error lines
        feedback.detailed_info += `🚨 Error: ${errorLines.join(' | ')}`;
    }
}

// Try to get system statistics
try {
    exec('python3 enhanced_pipeline_monitor.py stats ' + taskName, 
        { cwd: '/home/jc/Documents/Horse-race-ai-v2.04', timeout: 5000 },
        (error, stdout, stderr) => {
            if (!error && stdout) {
                try {
                    feedback.statistics = JSON.parse(stdout);
                } catch (e) {
                    // Ignore parse errors
                }
            }

            // Send the feedback message
            msg.payload = feedback;
            msg.topic = `feedback_${taskName}`;
            node.send(msg);
        }
    );
} catch (e) {
    // If stats fail, send feedback without statistics
    msg.payload = feedback;
    msg.topic = `feedback_${taskName}`;
    node.send(msg);
}

// Don't send message immediately - will be sent after stats are collected
return null;

// Format the feedback data into attractive HTML
const feedback = msg.payload;

if (!feedback || !feedback.task_name) {
    return null;
}

let html = `
<div style="padding: 15px; margin: 10px 0; border-radius: 8px; 
    background: linear-gradient(135deg, ${feedback.status === 'success' ? '#4CAF50' : '#f44336'}, 
    ${feedback.status === 'success' ? '#8BC34A' : '#FF5722'});
    color: white; box-shadow: 0 4px 8px rgba(0,0,0,0.2);">

    <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px;">
        <h3 style="margin: 0; font-size: 18px;">
            ${feedback.status === 'success' ? '✅' : '❌'} ${feedback.task_name.toUpperCase()}
        </h3>
        <span style="font-size: 14px; opacity: 0.9;">${feedback.timestamp}</span>
    </div>

    <div style="background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px; margin-bottom: 10px;">
        <strong>${feedback.user_message}</strong>
    </div>

    <div style="background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px; font-family: monospace; font-size: 12px;">
        ${feedback.detailed_info.replace(/\n/g, '<br>')}
    </div>`;

// Add statistics if available
if (feedback.statistics && feedback.statistics.overall_stats) {
    const stats = feedback.statistics.overall_stats;
    html += `
    <div style="margin-top: 10px; padding: 10px; background: rgba(255,255,255,0.1); border-radius: 5px;">
        <h4 style="margin: 0 0 5px 0;">📊 Statistics Summary</h4>
        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(120px, 1fr)); gap: 10px; font-size: 12px;">
            <div><strong>Success Rate:</strong> ${stats.success_rate}%</div>
            <div><strong>Duration:</strong> ${stats.average_duration}s</div>
            <div><strong>Data Processed:</strong> ${stats.data_processed_mb.toFixed(2)} MB</div>
            <div><strong>Tasks:</strong> ${stats.successful_tasks}/${stats.total_tasks}</div>
        </div>
    </div>`;
}

// Add recommendations if available
if (feedback.statistics && feedback.statistics.success_summary && feedback.statistics.success_summary.recommendations) {
    const recommendations = feedback.statistics.success_summary.recommendations;
    html += `
    <div style="margin-top: 10px; padding: 10px; background: rgba(255,255,255,0.1); border-radius: 5px;">
        <h4 style="margin: 0 0 5px 0;">💡 Recommendations</h4>
        <ul style="margin: 0; padding-left: 20px; font-size: 12px;">
            ${recommendations.map(rec => `<li>${rec}</li>`).join('')}
        </ul>
    </div>`;
}

html += '</div>';

// Store in context for history
let feedbackHistory = flow.get('feedbackHistory') || [];
feedbackHistory.unshift({
    task: feedback.task_name,
    status: feedback.status,
    timestamp: feedback.timestamp,
    message: feedback.user_message
});

// Keep only last 10 items
if (feedbackHistory.length > 10) {
    feedbackHistory = feedbackHistory.slice(0, 10);
}
flow.set('feedbackHistory', feedbackHistory);

msg.payload = html;
return msg;

// Format comprehensive statistics for display
try {
    const stats = JSON.parse(msg.payload);

    if (stats.message) {
        msg.payload = `<div style="padding: 15px; background: #ff9800; color: white; border-radius: 8px;">
            <h3>📊 Pipeline Statistics</h3>
            <p>${stats.message}</p>
        </div>`;
        return msg;
    }

    const overall = stats.overall_stats;
    const success = stats.success_summary;

    let html = `
    <div style="padding: 15px; background: linear-gradient(135deg, #2196F3, #21CBF3); color: white; border-radius: 8px; margin: 10px 0;">
        <h3 style="margin: 0 0 15px 0;">📊 Pipeline Statistics Overview</h3>

        <div style="display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr)); gap: 15px; margin-bottom: 15px;">
            <div style="background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px;">
                <h4 style="margin: 0 0 5px 0;">📈 Performance</h4>
                <div>Success Rate: <strong>${overall.success_rate}%</strong></div>
                <div>Average Duration: <strong>${overall.average_duration.toFixed(2)}s</strong></div>
                <div>Total Runtime: <strong>${(overall.total_duration / 60).toFixed(1)} min</strong></div>
            </div>

            <div style="background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px;">
                <h4 style="margin: 0 0 5px 0;">📊 Task Summary</h4>
                <div>Total Tasks: <strong>${overall.total_tasks}</strong></div>
                <div>Successful: <strong style="color: #4CAF50;">${overall.successful_tasks}</strong></div>
                <div>Failed: <strong style="color: #f44336;">${overall.failed_tasks}</strong></div>
                <div>Running: <strong style="color: #FF9800;">${overall.running_tasks}</strong></div>
            </div>

            <div style="background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px;">
                <h4 style="margin: 0 0 5px 0;">💾 Data Processing</h4>
                <div>Data Processed: <strong>${overall.data_processed_mb.toFixed(2)} MB</strong></div>
                <div>System Load: <strong>${stats.performance_metrics.system_load ? (stats.performance_metrics.system_load.cpu_percent || 0).toFixed(1) : 0}% CPU</strong></div>
            </div>
        </div>

        <div style="background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px;">
            <h4 style="margin: 0 0 10px 0;">✅ ${success.message}</h4>
            <p style="margin: 0; opacity: 0.9;">${success.details}</p>
        </div>`;

    // Add recommendations
    if (success.recommendations && success.recommendations.length > 0) {
        html += `
        <div style="background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px; margin-top: 10px;">
            <h4 style="margin: 0 0 10px 0;">💡 Recommendations</h4>
            <ul style="margin: 0; padding-left: 20px;">
                ${success.recommendations.map(rec => `<li>${rec}</li>`).join('')}
            </ul>
        </div>`;
    }

    // Add performance insights
    if (stats.performance_metrics.fastest_task) {
        html += `
        <div style="background: rgba(255,255,255,0.1); padding: 10px; border-radius: 5px; margin-top: 10px;">
            <h4 style="margin: 0 0 5px 0;">🏃 Performance Insights</h4>
            <div style="font-size: 14px;">
                <div>⚡ Fastest Task: <strong>${stats.performance_metrics.fastest_task}</strong></div>
                <div>🐌 Slowest Task: <strong>${stats.performance_metrics.slowest_task}</strong></div>
                <div>📈 Most Data Produced: <strong>${stats.performance_metrics.most_data_produced}</strong></div>
            </div>
        </div>`;
    }

    html += '</div>';

    msg.payload = html;

} catch (e) {
    msg.payload = `<div style="padding: 15px; background: #f44336; color: white; border-radius: 8px;">
        <h3>❌ Statistics Error</h3>
        <p>Failed to parse statistics: ${e.message}</p>
        <p>Raw output: ${msg.payload}</p>
    </div>`;
}

return msg;
